const now = new Date();
const dateKst = new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Asia/Seoul'
}).format(now);

const targetUsers = [
  {
    name: '김진욱',
    email: 'jwkim@vms-solutions.com'
  }
];

return [
  {
    json: {
      dateKst,
      targetUsers,
      requestBody: {
        Schedules: targetUsers.map((user) => user.email),
        StartTime: {
          dateTime: `${dateKst}T00:00:00`,
          timeZone: 'Asia/Seoul'
        },
        EndTime: {
          dateTime: `${dateKst}T23:59:59`,
          timeZone: 'Asia/Seoul'
        },
        availabilityViewInterval: 30
      }
    }
  }
];

const source = $('Build Schedule Request').first().json;
const targetUsers = Array.isArray(source.targetUsers) ? source.targetUsers : [];
const targetMap = new Map(
  targetUsers.map((user) => [user.email.toLowerCase(), user])
);

const schedules = Array.isArray($json.value) ? $json.value : [];

if (schedules.length === 0) {
  return [
    {
      json: {
        date: source.dateKst,
        targetCount: targetUsers.length,
        hasSchedule: false,
        note: 'No schedule data returned.'
      }
    }
  ];
}

return schedules.map((entry) => {
  const email = (entry.scheduleId ?? '').toString();
  const user = targetMap.get(email.toLowerCase()) ?? {
    name: email,
    email
  };
  const scheduleItems = Array.isArray(entry.scheduleItems) ? entry.scheduleItems : [];
  const hasSchedule = scheduleItems.length > 0 || /[1-3]/.test(entry.availabilityView ?? '');

  return {
    json: {
      date: source.dateKst,
      name: user.name,
      email: user.email,
      hasSchedule,
      busyCount: scheduleItems.length,
      availabilityView: entry.availabilityView ?? '',
      timeRanges: scheduleItems.map((item) => ({
        start: item.start?.dateTime ?? '',
        end: item.end?.dateTime ?? '',
        status: item.status ?? ''
      }))
    }
  };
});
